      case 'notice':
        return ChatItemNotice(ChatNoticeItem.fromJson(json));
      case 'usage':
        return ChatItemUsage(ChatUsageItem.fromJson(json));
      default:
        return ChatItemUnknown(json);
    }
  }

  /// Diskriminant qiymati (`kind`).
  String get tag;

  Map<String, dynamic> toJson();
}

